67	/// T-bit is set, then ≻⋈, then ⊥ iff the F-bit is set, then ≺ (the clear —
68	/// banked if the fork opened before it, exposed otherwise), then ⋈ and ∋
69	/// iff the fork bit is set, then ⊞ iff the I-bit is set, then ⊙⊡⊣.
70	/// Verified pairwise distinct across all 16 against the real kernel.
71	pub const HEX_WORDS: [&str; 16] = [
72	    "⊢≻⋈≺⊙⊡⊣",             // 0x0  T=0 F=0 I=0 fork=0
73	    "⊢⊤≻⋈≺⊙⊡⊣",           // 0x1  T=1 F=0 I=0 fork=0
74	    "⊢≻⋈⊥≺⊙⊡⊣",           // 0x2  T=0 F=1 I=0 fork=0
75	    "⊢⊤≻⋈⊥≺⊙⊡⊣",         // 0x3  T=1 F=1 I=0 fork=0
