90	/// Convert N (decimal string) to hex, then concatenate each nibble's
91	/// canonical word, most-significant nibble first.
92	pub fn digit_encode(n_str: &str) -> String {
93	    let n: BigUint = match trim(n_str).parse() { Ok(v) => v, Err(_) => return String::new() };
94	    let hex = n.to_str_radix(16);
95	    let mut out = String::new();
96	    for c in hex.chars() {
97	        if let Some(d) = c.to_digit(16) {
98	            out.push_str(HEX_WORDS[d as usize]);
99	        }
100	    }
101	    out
102	}
103	
104	/// Small trial divisors for `factor`'s search — plain arithmetic, not a
105	/// structural claim. The verdict on any candidate this produces is
106	/// still read from `is_prime`, never assumed from the search itself.
107	pub const TRIAL_DIVISION_BOUND: u64 = 10_000_000;
108	
109	/// `find`'s decrement search costs one full hex_encode + cycle_landings per
110	/// step. `cycle_landings` walks the whole word once per rotation, so its
111	/// cost is quadratic in word length where the old single-cut `banked_walk`
112	/// was linear — measured before this constant was set to whatever value
113	/// keeps that cost interactive.
114	pub const SCAN_CAP: u64 = 100_000;
115	
116	pub const WORD: &str = "⊢⊙∈≻⊤⋈≺⊥⊞∋⊡⋈⊙⊣";
117	pub const PERIOD: usize = 14;
118	pub const PHASE_BEARING: bool = true;
119	pub const FROBENIUS_VERDICT: &str = "T";
120	pub const ARTIFACT_SLUG: &str = "winding_period_of_the_primes_on_the_number_line";
121	pub const OB3ECT_DIR: &str = "/home/mrnob0dy666/ob3ect/digital/winding_period_of_the_primes_on_the_number_line";
122	
123	/// The 12-slot tuple at the artifact's foundation.
124	pub const TUPLE: [&str; 12] = [
125	    "uninitialized_number_line", "winding_closure", "prime_ascent", "gap_descent",
126	    "sequential_engagement", "kinetic_freezing", "chiral_bifurcation",
127	    "dialetheic_reunion", "self_modeling_density", "irregular_gap",
128	    "critical_threshold", "integer_invariant",
129	];
130	
131	pub const LANDINGS: [&str; 14] = [
132	    "A", "A", "A", "Ftf", "Ftf", "Ftf", "Ftf", "Ftf", "tf", "T", "T", "A", "A", "A",
133	];
