135	// ── Decimal string trim/compare — only what `find` and `factor` need ───────
136	
137	/// Strip leading zeros, return "0" if all zero.
138	fn trim(s: &str) -> String {
139	    let bytes = s.as_bytes();
140	    let mut i = 0;
141	    while i + 1 < bytes.len() && bytes[i] == b'0' {
142	        i += 1;
143	    }
144	    s[i..].to_string()
145	}
146	
147	/// True if a is less than b (both non-empty decimal).
148	fn lt(a: &str, b: &str) -> bool {
149	    let ta = trim(a);
150	    let tb = trim(b);
151	    if ta.len() != tb.len() { return ta.len() < tb.len(); }
152	    ta < tb
153	}
154	
155	/// a - b, assumes a >= b. Both non-negative.
156	fn sub(a: &str, b: &str) -> String {
157	    let ta = trim(a);
158	    let tb = trim(b);
159	    let av: Vec<u8> = ta.bytes().rev().collect();
160	    let bv: Vec<u8> = tb.bytes().rev().collect();
161	    let mut out: Vec<u8> = Vec::new();
162	    let mut borrow: u8 = 0;
163	    for i in 0..av.len() {
164	        let x = av[i] - b'0';
165	        let y = if i < bv.len() { bv[i] - b'0' } else { 0 } + borrow;
166	        if x >= y {
167	            out.push(b'0' + (x - y));
168	            borrow = 0;
169	        } else {
170	            out.push(b'0' + (x + 10 - y));
171	            borrow = 1;
172	        }
173	    }
174	    let s: String = out.iter().rev().map(|c| *c as char).collect();
175	    trim(&s)
176	}
177	
178	// ── Primality: digit encoding + the kernel's own closure check ─────────
179	
180	/// The three outcomes the closure check can reach. Never collapsed to a
181	/// bool: Undetermined is a real, distinct answer (the vacuous case — no
182	/// clear ever fired, so nothing was ever at risk), not a stand-in for
183	/// either Prime or Composite.
184	#[derive(Clone, Copy, PartialEq, Eq, Debug)]
185	pub enum PrimeVerdict { Prime, Composite, Undetermined }
186	
187	/// N is prime iff the Grammar's own tri-ancestral verdict on its hex-encoded
188	/// word is T — every FSPLIT3 pairs with a FFUSE3 around the word read AS A
189	/// LOOP, and real work ran inside at least one paired region: a closed,
190	/// non-trivial transformation. N (paired but no work ran anywhere — void)
191	/// is Undetermined. B (a fork left open) and F (a fuse with nothing to
192	/// pair with) both fail to close, so both read Composite.
193	///
194	/// This is not a rule built on top of the register content — it is the
195	/// Grammar's own existing verdict function
196	/// (`imasm_core::imasm16_3::tri_ancestral_verdict`, exposed here as
197	/// `tri_ancestral_word_verdict`), already used everywhere an ob3ect reports
198	/// its own tri-ancestral verdict. Two earlier attempts built a rule on top
199	/// of the register content instead of asking what the Grammar already
200	/// computes: a single-cut banking check (`banked_walk` at k=0 alone) was
201	/// proven to read only the leading digit and nothing after it; a
202	/// register-A-anywhere check on the full orbit fixed that but turned out
203	/// to be satisfied by nearly any sufficiently long word, discriminating
204	/// almost nothing. This reads the word's own verdict instead of inventing
205	/// one, and that verdict is inherently a whole-loop fact: pairing is
206	/// cyclic, so it is not one cut among many, it does not need the orbit
207	/// walked at all.
208	pub fn is_prime(a: &str) -> PrimeVerdict {
209	    let t = trim(a);
210	    let n: BigUint = match t.parse() {
211	        Ok(v) => v,
212	        Err(_) => return PrimeVerdict::Composite,
213	    };
214	    if n < BigUint::from(2u32) { return PrimeVerdict::Composite; }
215	
216	    let word = digit_encode(&t);
217	    match tri_ancestral_word_verdict(&word) {
218	        Some('T') => PrimeVerdict::Prime,
219	        Some('N') => PrimeVerdict::Undetermined,
220	        Some('B') | Some('F') => PrimeVerdict::Composite,
221	        Some(_) | None => PrimeVerdict::Undetermined,
222	    }
223	}
224	
225	fn prime_verdict_str(v: PrimeVerdict) -> &'static str {
226	    match v {
227	        PrimeVerdict::Prime => "PRIME",
228	        PrimeVerdict::Composite => "COMPOSITE",
229	        PrimeVerdict::Undetermined => "UNDETERMINED (no clear ever fired on the digit-encoded word — nothing was ever at risk)",
230	    }
231	}
232	
233	// ── Output formatters ───────────────────────────────────────────────────────
234	
235	pub fn word() -> String {
236	    format!(
237	        "prime_winding word: {}\n  period: {}\n  glyphs: {} (12 opcodes + 2 anchors)",
238	        WORD, PERIOD, WORD.chars().count()
239	    )
240	}
241	
242	/// Find the nearest prime ≤ n. n is a decimal string (arbitrary precision).
243	/// Stops the moment the search meets an Undetermined verdict — it does
244	/// not step past a number outside its reach.
245	///
246	/// The old version of this search jumped past a whole block of numbers on
247	/// a fact that no longer holds: `is_prime` used to read only the leading
248	/// digit, so an entire digit-count's worth of numbers shared one verdict
249	/// and could be skipped at once. Now that the verdict comes from the full
250	/// ROTAT orbit and depends on every digit, that shortcut is gone and there
251	/// is no known way to jump to the answer — decrementing one at a time is
252	/// the search itself, not a stand-in for a faster one. `SCAN_CAP` bounds
253	/// the step count at a value measured to stay interactive; past that it
254	/// reports OutOfReach, stating what was scanned rather than hanging.
255	pub fn find(n: &str) -> String {
256	    if lt(n, "2") {
257	        return format!("prime_winding find {}: no primes ≤ {}", n, n);
258	    }
259	    let start = trim(n);
260	    let mut m = start.clone();
261	    let mut steps: u64 = 0;
262	    loop {
263	        match is_prime(&m) {
264	            PrimeVerdict::Prime => {
265	                return if m == start {
266	                    format!("prime_winding find {}: {} IS PRIME\n  glyph: {}", n, n, WORD)
267	                } else {
268	                    format!(
269	                        "prime_winding find {}: {} is composite, nearest prime ≤ {} is {}\n  glyph: {}",
270	                        n, n, n, m, WORD
271	                    )
272	                };
273	            }
274	            PrimeVerdict::Undetermined => {
275	                return format!(
276	                    "prime_winding find {}: {} is vacuous on its digit-encoded word — no clear ever fired, cannot certify further",
277	                    n, m
278	                );
279	            }
280	            PrimeVerdict::Composite => {}
281	        }
282	        if lt(&m, "2") {
283	            return format!("prime_winding find {}: no prime found below", n);
284	        }
285	        m = sub(&m, "1");
286	        steps += 1;
287	        if steps > SCAN_CAP {
288	            return format!(
289	                "prime_winding find {}: OutOfReach — {} step(s) scanned below {} with no closing or vacuous word, scan halted at {}",
290	                n, steps, n, m
291	            );
292	        }
293	    }
294	}
295	
296	/// Factor n (decimal string, arbitrary precision). Closure alone answers
297	/// whether N is prime, not what its factors are, so this walks small
298	/// trial divisors to find them — plain arithmetic, a search strategy,
299	/// not a Grammar claim — and every cofactor's status (prime, composite,
300	/// undetermined) is read from `is_prime`, never assumed from the search.

