            let mut j: u64 = 0;
            let upper = power.min(m);
            while j < upper {
                x = brent_f(&x, &c, n);
                let d = if x > y { &x - &y } else { &y - &x };
                let g = big_gcd(d, n.clone());
                if !g.is_one() && g != *n { return Some(g); }
