    builder.arg(&mut d_truth);
    builder.arg(&mut d_falsity);
    builder.arg(&n);
    let cfg = LaunchConfig::for_num_elems(n as u32);
    unsafe { builder.launch(cfg) }.map_err(|e| format!("launch {pass_label} failed: {e}"))?;
