        }
    ));

    let wind = WINDING_INVARIANT.fetch_add(1, Ordering::SeqCst) + 1;
    trace.push_str(&format!("         ⊡ winding invariant incremented, never decremented: now {wind}\n"));

    Ok((t, f))
}

/// Runs the repaired protocol word for real: checks it against the
