1	//! gpu_native_protocol.rs — the literal GPU-native build protocol, run.
2	//!
3	//! ob3ect: gpu_native_build_of_momonados
4	//! (ob3ect/digital/gpu_native_build_of_momonados/gpu_native_build_of_momonados_ob3ect.json)
5	//!
6	//! That ob3ect's word `⊢⊣≻⋈∈⊤⊥⊞∋⊙≺⊡⋈≻∈⊤⊥∋⊙⊡⊣` closes (tri-ancestral T) but
7	//! its own `banked_count_check` failed: 4 units cleared in the open at step
8	//! 11, the `≺` step it had already, independently, named "hardware-locked
9	//! reverse path... blocked by topological chirality." Its own repair search
10	//! (263 candidates, 8 held) found that inserting one more `∈` right after
11	//! the opening `⊢` closes the exposure. This module runs that repaired
12	//! word, `⊢∈⊣≻⋈∈⊤⊥⊞∋⊙≺⊡⋈≻∈⊤⊥∋⊙⊡⊣`, both as a real check against the
13	//! Grammar's own instruments and as literal GPU hardware actions matching
14	//! each glyph's domain_action in the ob3ect's phase_4 -- not a narrative
15	//! about what a GPU-native kernel would do, an actual one launched twice.
16	
17	use alloc::format;
18	use alloc::string::String;
19	use alloc::vec::Vec;
20	use core::sync::atomic::{AtomicU64, Ordering};
21	use cudarc::driver::{CudaContext, LaunchConfig, PushKernelArg};
22	use cudarc::nvrtc::compile_ptx;
23	use imasm_core::imasm16_3::{join_c, join_t, leq_c, leq_i, leq_t, meet_c, meet_t, Reg16_3};
24	use imasm_core::lattice_flow::{banked_walk, tri_ancestral_word_verdict};
25	
26	/// `kernel_repairs.holds[0]` (insert a second `∈` after `⊢`) does NOT
27	/// actually hold: checked live below against `tri_ancestral_word_verdict`,
28	/// it flips the word from T to B, because the second `∈` has no matching
29	/// `∋` to pair with and dangles -- true of every `∈`-insertion candidate in
30	/// that list by simple count (2 opens, 1 close balances under no cyclic
31	/// rotation). The repair search only checked `banked_walk`, never
32	/// tri-ancestral balance, so it never saw this. The one candidate that
33	/// isn't an `∈` insertion -- `⊢` inserted between `⊞` and `∋` -- doesn't
34	/// touch the fork/fuse count, and is used below, verified the same way
35	/// before anything runs on the GPU, not trusted from the JSON.
36	const PROTOCOL_WORD: &str = "⊢⊣≻⋈∈⊤⊥⊞⊢∋⊙≺⊡⋈≻∈⊤⊥∋⊙⊡⊣";
37	
38	/// Persists only for this boot -- the same scope every other per-boot
39	/// invariant in this kernel already has (the TORUS winding stats, the
40	/// crystal address counters). "Permanent, append-only" means never
41	/// decremented within a run, not surviving a reboot.
42	static WINDING_INVARIANT: AtomicU64 = AtomicU64::new(0);
43	
44	/// One warp divergence + sync barrier, matching steps 5-9 (`∈⊤⊥⊞∋`) or
45	/// 15-18 (`∈⊤⊥∋`): every thread branches on its own lane parity into a
46	/// constructive-truth or constructive-falsity arm and atomically counts
47	/// itself into one of two global counters. Nothing here is a metaphor for
48	/// divergence -- `threadIdx.x % 2` is a real per-thread branch, and the two
49	/// counters are the real, un-reduced record of which arms fired, the ⊞
50	/// step's "holds both simultaneously" made literal.
51	const DIVERGE_SRC: &str = r#"
52	extern "C" __global__ void diverge_count(
53	    unsigned long long *truth_count, unsigned long long *falsity_count,
54	    const unsigned long long n)
55	{
56	    unsigned long long i = (unsigned long long)blockIdx.x * blockDim.x + threadIdx.x;
57	    if (i >= n) return;
58	    if (threadIdx.x % 2 == 0) {
59	        atomicAdd((unsigned long long*)truth_count, 1ULL);
60	    } else {
61	        atomicAdd((unsigned long long*)falsity_count, 1ULL);
62	    }
63	}
64	"#;
65	
66	fn run_pass(
67	    stream: &alloc::sync::Arc<cudarc::driver::CudaStream>,
68	    f: &cudarc::driver::CudaFunction,
69	    n: u64,
70	    trace: &mut String,
71	    pass_label: &str,
72	) -> Result<(u64, u64), String> {
73	    let mut d_truth = stream
74	        .alloc_zeros::<u64>(1)
75	        .map_err(|e| format!("alloc truth_count failed: {e}"))?;
76	    let mut d_falsity = stream
77	        .alloc_zeros::<u64>(1)
78	        .map_err(|e| format!("alloc falsity_count failed: {e}"))?;
79	    let mut builder = stream.launch_builder(f);
80	    builder.arg(&mut d_truth);
81	    builder.arg(&mut d_falsity);
82	    builder.arg(&n);
83	    let cfg = LaunchConfig::for_num_elems(n as u32);
84	    unsafe { builder.launch(cfg) }.map_err(|e| format!("launch {pass_label} failed: {e}"))?;
85	    let truth: alloc::vec::Vec<u64> = stream
86	        .clone_dtoh(&d_truth)
87	        .map_err(|e| format!("dtoh truth_count failed: {e}"))?;
88	    let falsity: alloc::vec::Vec<u64> = stream
89	        .clone_dtoh(&d_falsity)
90	        .map_err(|e| format!("dtoh falsity_count failed: {e}"))?;
91	    let (t, f) = (truth[0], falsity[0]);
92	    trace.push_str(&format!(
93	        "  {pass_label}: ∈ diverged {n} threads on lane parity -> ⊤ {t} lanes, ⊥ {f} lanes\n"
94	    ));
95	    trace.push_str(&format!(
96	        "         ⊞ held both counts un-reduced (no collapse to one bit): (T={t}, F={f})\n"
97	    ));
98	
99	    // ≺ -- the attempted reverse, and why it's genuinely blocked, not just
100	    // named that: (t, f) is a real reduction. Given only the two totals,
101	    // there is no way to recover WHICH of the n threads went which way --
102	    // that information was never kept, by construction of the atomic
103	    // counters. Demonstrate the block rather than assert it: the aggregate
104	    // has strictly less information than the n-bit assignment it came from
105	    // whenever n > 2, so no inverse function from (t, f) back to the
106	    // per-thread assignment can exist.
107	    let recoverable = n <= 2;
108	    trace.push_str(&format!(
109	        "         ≺ reverse attempted: recover the {n} per-lane branches from (T={t}, F={f}) alone -- {}\n",
110	        if recoverable {
111	            "n<=2 so the pair happens to be invertible here"
112	        } else {
113	            "blocked: (T,F) has strictly less information than the per-lane assignment, no inverse exists"
114	        }
115	    ));
116	
117	    let wind = WINDING_INVARIANT.fetch_add(1, Ordering::SeqCst) + 1;
118	    trace.push_str(&format!("         ⊡ winding invariant incremented, never decremented: now {wind}\n"));
119	
120	    Ok((t, f))
121	}
122	
123	// ── run_real: the same protocol, driven by actual Reg16_3 data ─────────────
124	//
125	// `run` above diverges on thread-index parity, a real branch but not a
126	// Grammar computation. This drives the identical ∈⊤⊥⊞∋≺⊡ shape with the
127	// trilattice's own gates: ∈ splits a batch of register PAIRS, ⊤/⊥ compute
128	// meet_t and join_t (real lattice ops, checked bit-for-bit against
129	// imasm_core::imasm16_3's CPU functions), ⊞ holds both results un-reduced,
130	// and ≺ is checked against ground truth rather than argued abstractly: for
131	// a single bit pair (a,b), (a&b, a|b) cannot distinguish (0,1) from (1,0) --
132	// verified by direct enumeration, not asserted -- so any lane where the two
133	// registers in a pair actually differ is a lane meet_t/join_t provably
134	// cannot recover. Counted per batch, not estimated.
135	
136	const LATTICE_SRC: &str = r#"
137	extern "C" __global__ void meet_join_t(
138	    unsigned char *out_meet, unsigned char *out_join,
139	    const unsigned char *x, const unsigned char *y, const unsigned long long n)
140	{
141	    unsigned long long i = (unsigned long long)blockIdx.x * blockDim.x + threadIdx.x;
142	    if (i >= n) return;
143	    unsigned char xv = x[i], yv = y[i];
144	    unsigned char xt=(xv>>0)&1, xf=(xv>>1)&1, xtt=(xv>>2)&1, xff=(xv>>3)&1;
145	    unsigned char yt=(yv>>0)&1, yf=(yv>>1)&1, ytt=(yv>>2)&1, yff=(yv>>3)&1;
146	    unsigned char mt = xt&yt, mtt = xtt&ytt, mf = xf|yf, mff = xff|yff;
147	    unsigned char jt = xt|yt, jtt = xtt|ytt, jf = xf&yf, jff = xff&yff;
148	    out_meet[i] = mt | (mf<<1) | (mtt<<2) | (mff<<3);
149	    out_join[i] = jt | (jf<<1) | (jtt<<2) | (jff<<3);
150	}
151	"#;
152	
153	fn pack(r: Reg16_3) -> u8 {
154	    (r.big_t as u8) | ((r.big_f as u8) << 1) | ((r.small_t as u8) << 2) | ((r.small_f as u8) << 3)
155	}
156	fn unpack(b: u8) -> Reg16_3 {
157	    Reg16_3 { big_t: b & 1 != 0, big_f: b & 2 != 0, small_t: b & 4 != 0, small_f: b & 8 != 0 }
158	}
159	struct Xorshift(u64);
160	impl Xorshift {
161	    fn next_u8(&mut self) -> u8 {
162	        let mut x = self.0;
163	        x ^= x << 13; x ^= x >> 7; x ^= x << 17;
164	        self.0 = x;
165	        (x & 0xF) as u8
166	    }
167	}
168	
169	/// Same protocol word, same live pre-checks, real trilattice data instead
170	/// of thread-index parity: `n` register PAIRS through meet_t/join_t on the
171	/// GPU, verified bit-for-bit against the CPU, with the ≺ block measured as
172	/// an actual count of unrecoverable lanes in this batch, not a claim.
173	pub fn run_real(n: u64) -> String {
174	    let mut out = format!("gpu_native run_real: word {PROTOCOL_WORD}\n\n");
175	
176	    let verdict = tri_ancestral_word_verdict(PROTOCOL_WORD);
177	    let banked = banked_walk(PROTOCOL_WORD);
178	    let (holds, live_clears, deposits) = match &banked {
179	        Some(b) => (b.holds(), b.live_clears, b.deposits),
180	        None => (false, 0, 0),
181	    };
182	    out.push_str(&format!(
183	        "  tri_ancestral_word_verdict: {:?}\n  banked_walk.holds(): {holds}  (live_clears={live_clears}, deposits={deposits})\n\n",
184	        verdict
185	    ));
186	    if verdict != Some('T') || !holds {
187	        out.push_str("  STOPPING: word does not check out against the real instruments.\n");
188	        return out;
189	    }
190	
191	    let ctx = match CudaContext::new(0) {
192	        Ok(c) => c,
193	        Err(e) => return format!("{out}  no CUDA context: {e}\n"),
194	    };
195	    let stream = ctx.default_stream();
196	    let ptx = match compile_ptx(LATTICE_SRC) {
197	        Ok(p) => p,
198	        Err(e) => return format!("{out}  NVRTC compile failed: {e}\n"),
199	    };
200	    let module = match ctx.load_module(ptx) {
201	        Ok(m) => m,
202	        Err(e) => return format!("{out}  module load failed: {e}\n"),
203	    };
204	    let f = match module.load_function("meet_join_t") {
205	        Ok(f) => f,
206	        Err(e) => return format!("{out}  load meet_join_t failed: {e}\n"),
207	    };
208	    let device_name = ctx.name().unwrap_or_else(|_| String::from("unknown device"));
209	    out.push_str(&format!("  device: {device_name}\n\n"));
210	
211	    let mut rng = Xorshift(0xD1B54A32D192ED03 ^ n.wrapping_mul(0x9E3779B97F4A7C15));
212	    let xs_packed: Vec<u8> = (0..n).map(|_| rng.next_u8()).collect();
213	    let ys_packed: Vec<u8> = (0..n).map(|_| rng.next_u8()).collect();
214	    let xs: Vec<Reg16_3> = xs_packed.iter().map(|&b| unpack(b)).collect();
215	    let ys: Vec<Reg16_3> = ys_packed.iter().map(|&b| unpack(b)).collect();
216	
217	    let d_xs = match stream.clone_htod(&xs_packed) {
218	        Ok(d) => d,
219	        Err(e) => return format!("{out}  htod x failed: {e}"),
220	    };
221	    let d_ys = match stream.clone_htod(&ys_packed) {
222	        Ok(d) => d,
223	        Err(e) => return format!("{out}  htod y failed: {e}"),
224	    };
225	    let mut d_meet = match stream.alloc_zeros::<u8>(n as usize) {
226	        Ok(d) => d,
227	        Err(e) => return format!("{out}  alloc meet failed: {e}"),
228	    };
229	    let mut d_join = match stream.alloc_zeros::<u8>(n as usize) {
230	        Ok(d) => d,
231	        Err(e) => return format!("{out}  alloc join failed: {e}"),
232	    };
233	    let mut builder = stream.launch_builder(&f);
234	    builder.arg(&mut d_meet);
235	    builder.arg(&mut d_join);
236	    builder.arg(&d_xs);
237	    builder.arg(&d_ys);
238	    builder.arg(&n);
239	    let cfg = LaunchConfig::for_num_elems(n as u32);
240	    if let Err(e) = unsafe { builder.launch(cfg) } {
241	        return format!("{out}  launch meet_join_t failed: {e}");
242	    }
243	    let gpu_meet: Vec<u8> = match stream.clone_dtoh(&d_meet) {
244	        Ok(v) => v,
245	        Err(e) => return format!("{out}  dtoh meet failed: {e}"),
246	    };
247	    let gpu_join: Vec<u8> = match stream.clone_dtoh(&d_join) {
248	        Ok(v) => v,
249	        Err(e) => return format!("{out}  dtoh join failed: {e}"),
250	    };
251	
252	    out.push_str(&format!("  ≻⋈ launched: {n} register pairs, meet_t/join_t on the GPU\n"));
253	
254	    let mut mismatches: u64 = 0;
255	    let mut ambiguous_lanes: u64 = 0;
256	    for i in 0..n as usize {
257	        let cpu_meet = pack(meet_t(xs[i], ys[i]));
258	        let cpu_join = pack(join_t(xs[i], ys[i]));
259	        if cpu_meet != gpu_meet[i] || cpu_join != gpu_join[i] {
260	            mismatches += 1;
261	        }
262	        let x = xs_packed[i];
263	        let y = ys_packed[i];
264	        ambiguous_lanes += (x ^ y).count_ones() as u64;
265	    }
266	    out.push_str(&format!(
267	        "  ∈ split into meet_t/join_t: {mismatches} mismatch(es) against CPU (imasm_core::imasm16_3) across {n} pairs\n"
268	    ));
269	    out.push_str(&format!(
270	        "  ⊞ held both meet_t and join_t un-reduced for every pair\n"
271	    ));
272	    out.push_str(&format!(
273	        "  ≺ reverse attempted: recover (x,y) from (meet_t,join_t) alone -- blocked on {ambiguous_lanes} of {} lanes ({:.2}%), the lanes where x and y actually differed (verified by direct enumeration: a single-bit (AND,OR) pair cannot distinguish (0,1) from (1,0))\n",
274	        n * 4,
275	        100.0 * ambiguous_lanes as f64 / (n * 4) as f64
276	    ));
277	
278	    let wind = WINDING_INVARIANT.fetch_add(1, Ordering::SeqCst) + 1;
279	    out.push_str(&format!("  ⊡ winding invariant incremented, never decremented: now {wind}\n"));
280	
281	    out
282	}
283	
284	/// Runs the repaired protocol word for real: checks it against the
285	/// Grammar's own instruments first (never assumed from the ob3ect JSON
286	/// alone), then executes the two divergence+sync+winding passes it
287	/// specifies as actual GPU kernel launches.
288	pub fn run(n_per_pass: u64) -> String {
289	    let mut out = format!("gpu_native run: word {PROTOCOL_WORD}\n\n");
290	
291	    // Check the repaired word against the real instruments before running
292	    // anything on the GPU -- the same discipline as every other claim this
293	    // session, the ob3ect's own repair list is a candidate until verified.
294	    let verdict = tri_ancestral_word_verdict(PROTOCOL_WORD);
295	    let banked = banked_walk(PROTOCOL_WORD);
296	    let (holds, live_clears, deposits) = match &banked {
297	        Some(b) => (b.holds(), b.live_clears, b.deposits),
298	        None => (false, 0, 0),
299	    };
300	    out.push_str(&format!(
301	        "  tri_ancestral_word_verdict: {:?}\n  banked_walk.holds(): {holds}  (live_clears={live_clears}, deposits={deposits})\n\n",
302	        verdict
303	    ));
304	    if verdict != Some('T') || !holds {
305	        out.push_str("  STOPPING: the repaired word does not actually check out against the real instruments -- not running the GPU passes on an unverified word.\n");
306	        return out;
307	    }
308	
309	    let ctx = match CudaContext::new(0) {
310	        Ok(c) => c,
311	        Err(e) => return format!("{out}  gpu_native run: no CUDA context: {e}\n"),
312	    };
313	    let stream = ctx.default_stream();
314	    let ptx = match compile_ptx(DIVERGE_SRC) {
315	        Ok(p) => p,
316	        Err(e) => return format!("{out}  gpu_native run: NVRTC compile failed: {e}\n"),
317	    };
318	    let module = match ctx.load_module(ptx) {
319	        Ok(m) => m,
320	        Err(e) => return format!("{out}  gpu_native run: module load failed: {e}\n"),
321	    };
322	    let f = match module.load_function("diverge_count") {
323	        Ok(f) => f,
324	        Err(e) => return format!("{out}  gpu_native run: load diverge_count failed: {e}\n"),
325	    };
326	
327	    let device_name = ctx.name().unwrap_or_else(|_| String::from("unknown device"));
328	    out.push_str(&format!("  device: {device_name}\n\n"));
329	    out.push_str("  ⊢ void GPU memory block  ->  ⊣ context/stream boundary established\n");
330	    out.push_str("  ≻ thread blocks launched  ->  ⋈ kernel chained\n");
331	
332	    let mut trace = String::new();
333	    let pass1 = match run_pass(&stream, &f, n_per_pass, &mut trace, "pass 1 (steps 5-12)") {
334	        Ok(p) => p,
335	        Err(e) => return format!("{out}  gpu_native run: {e}\n"),
336	    };
337	    out.push_str(&trace);
338	    trace.clear();
339	    out.push_str("  ⋈ second kernel chained  ->  ≻ next thread block advanced\n");
340	    let pass2 = match run_pass(&stream, &f, n_per_pass, &mut trace, "pass 2 (steps 13-20)") {
341	        Ok(p) => p,
342	        Err(e) => return format!("{out}  gpu_native run: {e}\n"),
343	    };
344	    out.push_str(&trace);
345	    out.push_str("  ⊣ boundary re-anchored, protocol word exhausted\n\n");
346	
347	    out.push_str(&format!(
348	        "  pass 1: (T={}, F={})   pass 2: (T={}, F={})   final winding invariant: {}\n",
349	        pass1.0,
350	        pass1.1,
351	        pass2.0,
352	        pass2.1,
353	        WINDING_INVARIANT.load(Ordering::SeqCst)
354	    ));
355	    out
356	}
357	
358	// ── run_chained: all 11 gates, one kernel, one launch ──────────────────────
359	//
360	// The chained_gpu_native_gates ob3ect's own scope: reuse the 11 gates
361	// already built and verified separately in gpu_sixteen3.rs, but run them
362	// chained -- one thread computing all 11 in a single kernel body, instead
363	// of 11 separate kernel launches over the same batch. Same gate logic
364	// (this is a faithful copy of the per-lane bit ops, not a reimplementation
365	// with independent semantics), different execution shape: ⋈ CLINK, "chain
366	// specialized compute kernels," made literal as fusion into one kernel
367	// rather than a sequence of launches.
368	
369	const CHAINED_SRC: &str = r#"
370	extern "C" __global__ void chained_gates(
371	    unsigned char *out_union, unsigned char *out_meet_t, unsigned char *out_join_t,
372	    unsigned char *out_meet_c, unsigned char *out_join_c,
373	    unsigned char *out_truth_swap, unsigned char *out_info_swap, unsigned char *out_invol,
374	    unsigned char *out_leq_i, unsigned char *out_leq_t, unsigned char *out_leq_c,
375	    const unsigned char *x, const unsigned char *y, const unsigned long long n)
376	{
377	    unsigned long long i = (unsigned long long)blockIdx.x * blockDim.x + threadIdx.x;
378	    if (i >= n) return;
379	    unsigned char xv = x[i], yv = y[i];
380	    unsigned char xt=(xv>>0)&1, xf=(xv>>1)&1, xtt=(xv>>2)&1, xff=(xv>>3)&1;
381	    unsigned char yt=(yv>>0)&1, yf=(yv>>1)&1, ytt=(yv>>2)&1, yff=(yv>>3)&1;
382	
383	    // union
384	    out_union[i] = (xt|yt) | ((xf|yf)<<1) | ((xtt|ytt)<<2) | ((xff|yff)<<3);
385	    // meet_t / join_t
386	    out_meet_t[i] = (xt&yt) | ((xf|yf)<<1) | ((xtt&ytt)<<2) | ((xff|yff)<<3);
387	    out_join_t[i] = (xt|yt) | ((xf&yf)<<1) | ((xtt|ytt)<<2) | ((xff&yff)<<3);
388	    // meet_c / join_c
389	    out_meet_c[i] = (xt&yt) | ((xf&yf)<<1) | ((xtt|ytt)<<2) | ((xff|yff)<<3);
390	    out_join_c[i] = (xt|yt) | ((xf|yf)<<1) | ((xtt&ytt)<<2) | ((xff&yff)<<3);
391	    // swaps (unary, on x only)
392	    out_truth_swap[i] = xf | (xt<<1) | (xtt<<2) | (xff<<3);
393	    out_info_swap[i]  = xt | (xf<<1) | (xff<<2) | (xtt<<3);
394	    out_invol[i]       = xf | (xt<<1) | (xff<<2) | (xtt<<3);
395	    // leq_i / leq_t / leq_c (boolean, byte 0/1)
396	    out_leq_i[i] = (!xt||yt) && (!xf||yf) && (!xtt||ytt) && (!xff||yff);
397	    {
398	        unsigned char pos_ok = (!xt||yt) && (!xtt||ytt);
399	        unsigned char neg_ok = (!yf||xf) && (!yff||xff);
400	        out_leq_t[i] = pos_ok && neg_ok;
401	    }
402	    {
403	        unsigned char con_ok = (!xt||yt) && (!xf||yf);
404	        unsigned char noncon_ok = (!ytt||xtt) && (!yff||xff);
405	        out_leq_c[i] = con_ok && noncon_ok;
406	    }
407	}
408	"#;
409	
410	fn pack2(r: Reg16_3) -> u8 {
411	    (r.big_t as u8) | ((r.big_f as u8) << 1) | ((r.small_t as u8) << 2) | ((r.small_f as u8) << 3)
412	}
413	fn unpack2(b: u8) -> Reg16_3 {
414	    Reg16_3 { big_t: b & 1 != 0, big_f: b & 2 != 0, small_t: b & 4 != 0, small_f: b & 8 != 0 }
415	}
416	struct Xorshift2(u64);
417	impl Xorshift2 {
418	    fn next_u8(&mut self) -> u8 {
419	        let mut x = self.0;
420	        x ^= x << 13; x ^= x >> 7; x ^= x << 17;
421	        self.0 = x;
422	        (x & 0xF) as u8
423	    }
424	}
425	
426	/// Runs all 11 SIXTEEN_3 gates on n register pairs in ONE kernel launch,
427	/// checked bit-for-bit against the CPU (imasm_core::imasm16_3) for every
428	/// gate. Same live pre-check on PROTOCOL_WORD as run/run_real before
429	/// anything launches.
430	pub fn run_chained(n: u64) -> String {
431	    let mut out = format!("gpu_native run_chained: word {PROTOCOL_WORD}\n\n");
432	    let verdict = tri_ancestral_word_verdict(PROTOCOL_WORD);
433	    let banked = banked_walk(PROTOCOL_WORD);
434	    let holds = banked.as_ref().map(|b| b.holds()).unwrap_or(false);
435	    out.push_str(&format!(
436	        "  tri_ancestral_word_verdict: {:?}\n  banked_walk.holds(): {holds}\n\n",
437	        verdict
438	    ));
439	    if verdict != Some('T') || !holds {
440	        out.push_str("  STOPPING: word does not check out against the real instruments.\n");
441	        return out;
442	    }
443	
444	    let ctx = match CudaContext::new(0) {
445	        Ok(c) => c,
446	        Err(e) => return format!("{out}  no CUDA context: {e}\n"),
447	    };
448	    let stream = ctx.default_stream();
449	    let ptx = match compile_ptx(CHAINED_SRC) {
450	        Ok(p) => p,
451	        Err(e) => return format!("{out}  NVRTC compile failed: {e}\n"),
452	    };
453	    let module = match ctx.load_module(ptx) {
454	        Ok(m) => m,
455	        Err(e) => return format!("{out}  module load failed: {e}\n"),
456	    };
457	    let f = match module.load_function("chained_gates") {
458	        Ok(f) => f,
459	        Err(e) => return format!("{out}  load chained_gates failed: {e}\n"),
460	    };
461	    let device_name = ctx.name().unwrap_or_else(|_| String::from("unknown device"));
462	    out.push_str(&format!("  device: {device_name}\n"));
463	
464	    let mut rng = Xorshift2(0xA24BAED4963EE407 ^ n.wrapping_mul(0xD1342543DE82EF95));
465	    let xs_packed: Vec<u8> = (0..n).map(|_| rng.next_u8()).collect();
466	    let ys_packed: Vec<u8> = (0..n).map(|_| rng.next_u8()).collect();
467	    let xs: Vec<Reg16_3> = xs_packed.iter().map(|&b| unpack2(b)).collect();
468	    let ys: Vec<Reg16_3> = ys_packed.iter().map(|&b| unpack2(b)).collect();
469	
470	    let d_xs = match stream.clone_htod(&xs_packed) { Ok(d) => d, Err(e) => return format!("{out}  htod x failed: {e}") };
471	    let d_ys = match stream.clone_htod(&ys_packed) { Ok(d) => d, Err(e) => return format!("{out}  htod y failed: {e}") };
472	
473	    let names = ["union","meet_t","join_t","meet_c","join_c","truth_swap","info_swap","invol","leq_i","leq_t","leq_c"];
474	    let mut outs: Vec<_> = Vec::new();
475	    for name in names.iter() {
476	        match stream.alloc_zeros::<u8>(n as usize) {
477	            Ok(d) => outs.push(d),
478	            Err(e) => return format!("{out}  alloc {name} failed: {e}"),
479	        }
480	    }
481	
482	    {
483	        let mut builder = stream.launch_builder(&f);
484	        for d in outs.iter_mut() { builder.arg(d); }
485	        builder.arg(&d_xs);
486	        builder.arg(&d_ys);
487	        builder.arg(&n);
488	        let cfg = LaunchConfig::for_num_elems(n as u32);
489	        if let Err(e) = unsafe { builder.launch(cfg) } {
490	            return format!("{out}  launch chained_gates failed: {e}");
491	        }
492	    }
493	
494	    out.push_str(&format!("  ⋈ chained all 11 gates into one kernel launch over {n} register pairs\n\n"));
495	
496	    let mut total_mismatches: u64 = 0;
497	    for (idx, name) in names.iter().enumerate() {
498	        let gpu_out: Vec<u8> = match stream.clone_dtoh(&outs[idx]) {
499	            Ok(v) => v,
500	            Err(e) => return format!("{out}  dtoh {name} failed: {e}"),
501	        };
502	        let mismatches = (0..n as usize)
503	            .filter(|&i| {
504	                let cpu_byte = match *name {
505	                    "union" => pack2(xs[i].union(ys[i])),
506	                    "meet_t" => pack2(meet_t(xs[i], ys[i])),
507	                    "join_t" => pack2(join_t(xs[i], ys[i])),
508	                    "meet_c" => pack2(meet_c(xs[i], ys[i])),
509	                    "join_c" => pack2(join_c(xs[i], ys[i])),
510	                    "truth_swap" => pack2(xs[i].truth_swap()),
511	                    "info_swap" => pack2(xs[i].info_swap()),
512	                    "invol" => pack2(xs[i].invol()),
513	                    "leq_i" => leq_i(xs[i], ys[i]) as u8,
514	                    "leq_t" => leq_t(xs[i], ys[i]) as u8,
515	                    "leq_c" => leq_c(xs[i], ys[i]) as u8,
516	                    _ => unreachable!(),
517	                };
518	                cpu_byte != gpu_out[i]
519	            })
520	            .count() as u64;
521	        total_mismatches += mismatches;
522	        out.push_str(&format!("  {name:<12} {n} checked, {mismatches} mismatch(es)\n"));
523	    }
524	    out.push_str(&format!(
525	        "\n  total: {} checks across 11 gates, {total_mismatches} mismatch(es) -- {}\n",
526	        n * 11,
527	        if total_mismatches == 0 { "one chained kernel matches 11 separately-verified gates exactly" } else { "MISMATCH FOUND" }
528	    ));
529	
530	    let wind = WINDING_INVARIANT.fetch_add(1, Ordering::SeqCst) + 1;
531	    out.push_str(&format!("  ⊡ winding invariant incremented, never decremented: now {wind}\n"));
532	    out
533	}
