1	//! gpu_sixteen3_tensor_kernel.rs — the `sixteen3_gpu_tensor_kernel` ob3ect,
2	//! its own protocol shape, not the flat per-lane version already built.
3	//!
4	//! `gpu_sixteen3.rs` computes every gate as one branch-free expression per
5	//! thread -- correct, and already verified bit-for-bit at scale, but not
6	//! the shape this ob3ect's own phase_4 names. That word calls for, per
7	//! gate: `∈` split into a T-arm and an F-arm, `⊤`/`≻` compute the T-arm
8	//! (its own forward step), `⊥`/`≺` compute the F-arm (a REAL lane
9	//! permutation "if required by the gate" -- true for a swap, a no-op for a
10	//! combine), `∋` rejoin the two arms into one register, `⊞` hold the B
11	//! state where the result genuinely has both T and F set, `⋈` chain that
12	//! output into the NEXT gate's input, `⊙` a self-reference check, `⊡`
13	//! commit to memory, `⊣` close. Per `law_shape_is_content`: a kernel that
14	//! computes the identical bits via one expression is not this shape, so
15	//! this module builds the two-arm split/rejoin structure explicitly, gate
16	//! by gate, and chains three real gates through it -- union, meet_t, then
17	//! truth_swap (the one of the three that actually exercises step 6's
18	//! permutation) -- checked against the CPU at every stage, not just the end.
19	
20	use alloc::format;
21	use alloc::string::String;
22	use alloc::vec::Vec;
23	use cudarc::driver::{CudaContext, LaunchConfig, PushKernelArg};
24	use cudarc::nvrtc::compile_ptx;
25	use imasm_core::imasm16_3::{meet_t, Reg16_3};
26	use std::time::Instant;
27	
28	/// Three gates chained through the explicit T-arm/F-arm/rejoin shape:
29	///   stage 1: union(x, y)            -- combine, no permutation needed
30	///   stage 2: meet_t(stage1, z)      -- combine, chained input (⋈)
31	///   stage 3: truth_swap(stage2)     -- unary, REAL lane permutation (≺)
32	/// Each stage computes its T-arm (T,t lanes) and F-arm (F,f lanes)
33	/// separately before packing them together (∋), not as one expression.
34	const TENSOR_SRC: &str = r#"
35	extern "C" __global__ void tensor_chain(
36	    unsigned char *out_stage1, unsigned char *out_stage2, unsigned char *out_stage3,
37	    unsigned char *both_flags,
38	    const unsigned char *x, const unsigned char *y, const unsigned char *z,
39	    const unsigned long long n)
40	{
41	    unsigned long long i = (unsigned long long)blockIdx.x * blockDim.x + threadIdx.x;
42	    if (i >= n) return;
43	
44	    // ⊢ void state for this thread's slot -- nothing read yet.
45	    unsigned char xv = x[i], yv = y[i], zv = z[i];
46	
47	    // ── stage 1: union(x, y) ──
48	    // ∈ split into T-arm / F-arm lanes.
49	    unsigned char x_t = (xv>>0)&1, x_f = (xv>>1)&1, x_tt = (xv>>2)&1, x_ff = (xv>>3)&1;
50	    unsigned char y_t = (yv>>0)&1, y_f = (yv>>1)&1, y_tt = (yv>>2)&1, y_ff = (yv>>3)&1;
51	    // ⊤/≻ T-arm: this gate's forward step on the T,t lanes.
52	    unsigned char s1_t_arm  = (x_t | y_t) | ((x_tt | y_tt) << 2);
53	    // ⊥/≺ F-arm: union needs no lane permutation, its F-arm is a direct
54	    // combine, so the reverse-morphism step is the identity here.
55	    unsigned char s1_f_arm  = (x_f | y_f) | ((x_ff | y_ff) << 2);
56	    // ∋ rejoin T-arm and F-arm into one packed register.
57	    unsigned char stage1 = (s1_t_arm & 0x5) | ((s1_f_arm & 0x5) << 1);
58	    out_stage1[i] = stage1;
59	    // ⊞ hold the B state where this result genuinely has both T and F.
60	    unsigned char stage1_both = ((stage1 & 1) && ((stage1>>1)&1)) ? 1 : 0;
61	
62	    // ⋈ chain stage 1's output into stage 2's input.
63	    // ── stage 2: meet_t(stage1, z) ──
64	    unsigned char s1v_t = (stage1>>0)&1, s1v_f = (stage1>>1)&1, s1v_tt = (stage1>>2)&1, s1v_ff = (stage1>>3)&1;
65	    unsigned char z_t = (zv>>0)&1, z_f = (zv>>1)&1, z_tt = (zv>>2)&1, z_ff = (zv>>3)&1;
66	    unsigned char s2_t_arm = (s1v_t & z_t) | ((s1v_tt & z_tt) << 2);
67	    unsigned char s2_f_arm = (s1v_f | z_f) | ((s1v_ff | z_ff) << 2);
68	    unsigned char stage2 = (s2_t_arm & 0x5) | ((s2_f_arm & 0x5) << 1);
69	    out_stage2[i] = stage2;
70	    unsigned char stage2_both = ((stage2 & 1) && ((stage2>>1)&1)) ? 1 : 0;
71	
72	    // ⋈ chain stage 2's output into stage 3's input.
73	    // ── stage 3: truth_swap(stage2) -- unary, a REAL lane permutation. ──
74	    unsigned char s2v_t = (stage2>>0)&1, s2v_f = (stage2>>1)&1, s2v_tt = (stage2>>2)&1, s2v_ff = (stage2>>3)&1;
75	    // ⊤/≻ T-arm: truth_swap's T lane comes from F, unchanged t lane.
76	    unsigned char s3_t_arm = s2v_f | (s2v_tt << 2);
77	    // ⊥/≺ F-arm: truth_swap's F lane comes from T -- the permutation this
78	    // step exists to name, not a no-op like stages 1 and 2.
79	    unsigned char s3_f_arm = s2v_t | (s2v_ff << 2);
80	    unsigned char stage3 = (s3_t_arm & 0x5) | ((s3_f_arm & 0x5) << 1);
81	    out_stage3[i] = stage3;
82	    unsigned char stage3_both = ((stage3 & 1) && ((stage3>>1)&1)) ? 1 : 0;
83	
84	    both_flags[i] = stage1_both | (stage2_both << 1) | (stage3_both << 2);
85	    // ⊡/⊣ commit and close happen host-side on readback + stream sync.
86	}
87	"#;
88	
89	fn pack(r: Reg16_3) -> u8 {
90	    (r.big_t as u8) | ((r.big_f as u8) << 1) | ((r.small_t as u8) << 2) | ((r.small_f as u8) << 3)
91	}
92	fn unpack(b: u8) -> Reg16_3 {
93	    Reg16_3 { big_t: b & 1 != 0, big_f: b & 2 != 0, small_t: b & 4 != 0, small_f: b & 8 != 0 }
94	}
95	struct Xorshift(u64);
96	impl Xorshift {
97	    fn next_u8(&mut self) -> u8 {
98	        let mut x = self.0;
99	        x ^= x << 13; x ^= x >> 7; x ^= x << 17;
100	        self.0 = x;
101	        (x & 0xF) as u8
102	    }
103	}
104	
105	pub fn run(n: u64) -> String {
106	    let mut out = format!("gpu_sixteen3_tensor_kernel: chained union -> meet_t -> truth_swap, {n} register triples\n\n");
107	
108	    let ctx = match CudaContext::new(0) {
109	        Ok(c) => c,
110	        Err(e) => return format!("{out}  no CUDA context: {e}\n"),
111	    };
112	    let stream = ctx.default_stream();
113	    let device_name = ctx.name().unwrap_or_else(|_| String::from("unknown device"));
114	    out.push_str(&format!("  device: {device_name}\n"));
115	
116	    let ptx = match compile_ptx(TENSOR_SRC) {
117	        Ok(p) => p,
118	        Err(e) => return format!("{out}  NVRTC compile failed: {e}\n"),
119	    };
120	    let module = match ctx.load_module(ptx) {
121	        Ok(m) => m,
122	        Err(e) => return format!("{out}  module load failed: {e}\n"),
123	    };
124	    let f = match module.load_function("tensor_chain") {
125	        Ok(f) => f,
126	        Err(e) => return format!("{out}  load tensor_chain failed: {e}\n"),
127	    };
128	
129	    let t_gen = Instant::now();
130	    let mut rng = Xorshift(0xC2B2AE3D27D4EB4F ^ n.wrapping_mul(0x165667B19E3779F9));
131	    let xs_packed: Vec<u8> = (0..n).map(|_| rng.next_u8()).collect();
132	    let ys_packed: Vec<u8> = (0..n).map(|_| rng.next_u8()).collect();
133	    let zs_packed: Vec<u8> = (0..n).map(|_| rng.next_u8()).collect();
134	    let gen_elapsed = t_gen.elapsed();
135	
136	    let t_htod = Instant::now();
137	    let d_x = match stream.clone_htod(&xs_packed) { Ok(d) => d, Err(e) => return format!("{out}  htod x: {e}") };
138	    let d_y = match stream.clone_htod(&ys_packed) { Ok(d) => d, Err(e) => return format!("{out}  htod y: {e}") };
139	    let d_z = match stream.clone_htod(&zs_packed) { Ok(d) => d, Err(e) => return format!("{out}  htod z: {e}") };
140	    let mut d_s1 = match stream.alloc_zeros::<u8>(n as usize) { Ok(d) => d, Err(e) => return format!("{out}  alloc s1: {e}") };
141	    let mut d_s2 = match stream.alloc_zeros::<u8>(n as usize) { Ok(d) => d, Err(e) => return format!("{out}  alloc s2: {e}") };
142	    let mut d_s3 = match stream.alloc_zeros::<u8>(n as usize) { Ok(d) => d, Err(e) => return format!("{out}  alloc s3: {e}") };
143	    let mut d_both = match stream.alloc_zeros::<u8>(n as usize) { Ok(d) => d, Err(e) => return format!("{out}  alloc both: {e}") };
144	
145	    {
146	        let mut builder = stream.launch_builder(&f);
147	        builder.arg(&mut d_s1);
148	        builder.arg(&mut d_s2);
149	        builder.arg(&mut d_s3);
150	        builder.arg(&mut d_both);
151	        builder.arg(&d_x);
152	        builder.arg(&d_y);
153	        builder.arg(&d_z);
154	        builder.arg(&n);
155	        let cfg = LaunchConfig::for_num_elems(n as u32);
156	        if let Err(e) = unsafe { builder.launch(cfg) } {
157	            return format!("{out}  launch tensor_chain failed: {e}");
158	        }
159	    }
160	    // ⊣ close the kernel boundary, synchronize before reading anything back.
161	    if let Err(e) = stream.synchronize() {
162	        return format!("{out}  synchronize failed: {e}");
163	    }
164	    let htod_launch_elapsed = t_htod.elapsed();
165	
166	    let t_dtoh = Instant::now();
167	    let gpu_s1: Vec<u8> = match stream.clone_dtoh(&d_s1) { Ok(v) => v, Err(e) => return format!("{out}  dtoh s1: {e}") };
168	    let gpu_s2: Vec<u8> = match stream.clone_dtoh(&d_s2) { Ok(v) => v, Err(e) => return format!("{out}  dtoh s2: {e}") };
169	    let gpu_s3: Vec<u8> = match stream.clone_dtoh(&d_s3) { Ok(v) => v, Err(e) => return format!("{out}  dtoh s3: {e}") };
170	    let gpu_both: Vec<u8> = match stream.clone_dtoh(&d_both) { Ok(v) => v, Err(e) => return format!("{out}  dtoh both: {e}") };
171	    let dtoh_elapsed = t_dtoh.elapsed();
172	    // ⊡ commit: the readback above IS the immutable record for this run.
173	
174	    out.push_str("  ⊢∈⊤≻⊥≺∋⊞ per gate, ⋈ chaining, three stages, checked against the CPU at each stage\n\n");
175	
176	    let t_verify = Instant::now();
177	    let mut mismatch_s1 = 0u64;
178	    let mut mismatch_s2 = 0u64;
179	    let mut mismatch_s3 = 0u64;
180	    let mut both_count = [0u64; 3];
181	    let mut self_ref_fail = 0u64;
182	    for i in 0..n as usize {
183	        let x = unpack(xs_packed[i]);
184	        let y = unpack(ys_packed[i]);
185	        let z = unpack(zs_packed[i]);
186	
187	        let cpu_s1 = x.union(y);
188	        if pack(cpu_s1) != gpu_s1[i] { mismatch_s1 += 1; }
189	
190	        let cpu_s2 = meet_t(cpu_s1, z);
191	        if pack(cpu_s2) != gpu_s2[i] { mismatch_s2 += 1; }
192	
193	        let cpu_s3 = cpu_s2.truth_swap();
194	        if pack(cpu_s3) != gpu_s3[i] { mismatch_s3 += 1; }
195	
196	        for stage in 0..3 {
197	            if (gpu_both[i] >> stage) & 1 == 1 { both_count[stage] += 1; }
198	        }
199	
200	        // ⊙ self-reference check: truth_swap is its own inverse -- applying
201	        // it again to the GPU's stage 3 output must recover stage 2 exactly.
202	        let un_swapped = unpack(gpu_s3[i]).truth_swap();
203	        if pack(un_swapped) != gpu_s2[i] { self_ref_fail += 1; }
204	    }
205	
206	    out.push_str(&format!(
207	        "  stage 1 union(x,y):        {n} checked, {mismatch_s1} mismatch(es) vs CPU\n"
208	    ));
209	    out.push_str(&format!(
210	        "  stage 2 meet_t(stage1,z):  {n} checked, {mismatch_s2} mismatch(es) vs CPU\n"
211	    ));
212	    out.push_str(&format!(
213	        "  stage 3 truth_swap(stage2): {n} checked, {mismatch_s3} mismatch(es) vs CPU\n"
214	    ));
215	    out.push_str(&format!(
216	        "  ⊞ B-state held (T and F both set): stage1 {} of {n}, stage2 {} of {n}, stage3 {} of {n}\n",
217	        both_count[0], both_count[1], both_count[2]
218	    ));
219	    out.push_str(&format!(
220	        "  ⊙ self-reference check (truth_swap is its own inverse): {self_ref_fail} of {n} failed to recover stage 2\n"
221	    ));
222	
223	    let verify_elapsed = t_verify.elapsed();
224	
225	    let total_mismatch = mismatch_s1 + mismatch_s2 + mismatch_s3 + self_ref_fail;
226	    out.push_str(&format!(
227	        "\n  {}\n",
228	        if total_mismatch == 0 {
229	            "all three chained stages match the CPU exactly, the self-reference check holds -- the split/rejoin/chain shape this ob3ect names, built and verified, not the flat expression already covered elsewhere"
230	        } else {
231	            "MISMATCH FOUND"
232	        }
233	    ));
234	
235	    out.push_str(&format!(
236	        "\n  TIMING n={n} gen_ms={:.3} htod_launch_sync_ms={:.3} dtoh_ms={:.3} cpu_verify_ms={:.3} total_ms={:.3}\n",
237	        gen_elapsed.as_secs_f64() * 1000.0,
238	        htod_launch_elapsed.as_secs_f64() * 1000.0,
239	        dtoh_elapsed.as_secs_f64() * 1000.0,
240	        verify_elapsed.as_secs_f64() * 1000.0,
241	        (gen_elapsed + htod_launch_elapsed + dtoh_elapsed + verify_elapsed).as_secs_f64() * 1000.0,
242	    ));
243	
244	    out
245	}
