1	//! gpu_sixteen3.rs — the SIXTEEN_3 trilattice's register gates, batched on GPU.
2	//!
3	//! ob3ect: sixteen3_gpu_tensor_kernel
4	//! (ob3ect/digital/sixteen3_gpu_tensor_kernel/sixteen3_gpu_tensor_kernel_ob3ect.json)
5	//!
6	//! `imasm_core::imasm16_3::Reg16_3` is a plain 4-bool tuple over the lanes
7	//! [T, F, t, f], and every lattice op on it (`union`, `meet_t`, `join_t`,
8	//! `meet_c`, `join_c`, `leq_i`, `leq_t`, `leq_c`, `truth_swap`, `info_swap`,
9	//! `invol`) is a fixed, data-independent per-lane bitwise op or permutation
10	//! -- never a branch on the value's content. That is a fixed-width
11	//! elementwise/permute kernel over an (N,4) boolean tensor, which is what
12	//! this module actually runs on GPU, verified bit-for-bit against the CPU
13	//! implementation it is a batched port of, not a reimplementation with its
14	//! own independent logic.
15	//!
16	//! Hosted only: no_std has no CUDA driver to link against. The bare-metal
17	//! build never sees this module at all (see main.rs's tree).
18	
19	use alloc::format;
20	use alloc::string::String;
21	use alloc::vec::Vec;
22	use cudarc::driver::{CudaContext, LaunchConfig, PushKernelArg};
23	use cudarc::nvrtc::compile_ptx;
24	use imasm_core::imasm16_3::{
25	    join_c, join_t, leq_c, leq_i, leq_t, meet_c, meet_t, Reg16_3,
26	};
27	
28	/// One CUDA source, three kernels: binary lattice ops, unary swaps, and the
29	/// leq_* order checks. All three read/write a register packed as one byte,
30	/// bit 0..3 = T,F,t,f -- the same lane order `Reg16_3` uses, just packed.
31	const KERNEL_SRC: &str = r#"
32	extern "C" __global__ void sixteen3_binary(
33	    unsigned char *out, const unsigned char *x, const unsigned char *y,
34	    const int op, const unsigned long long n)
35	{
36	    unsigned long long i = (unsigned long long)blockIdx.x * blockDim.x + threadIdx.x;
37	    if (i >= n) return;
38	    unsigned char xv = x[i], yv = y[i];
39	    unsigned char xt=(xv>>0)&1, xf=(xv>>1)&1, xtt=(xv>>2)&1, xff=(xv>>3)&1;
40	    unsigned char yt=(yv>>0)&1, yf=(yv>>1)&1, ytt=(yv>>2)&1, yff=(yv>>3)&1;
41	    unsigned char rt, rf, rtt, rff;
42	    if (op == 0) { // union: every lane OR
43	        rt = xt|yt; rf = xf|yf; rtt = xtt|ytt; rff = xff|yff;
44	    } else if (op == 1) { // meet_t: T,t AND; F,f OR
45	        rt = xt&yt; rtt = xtt&ytt; rf = xf|yf; rff = xff|yff;
46	    } else if (op == 2) { // join_t: T,t OR; F,f AND
47	        rt = xt|yt; rtt = xtt|ytt; rf = xf&yf; rff = xff&yff;
48	    } else if (op == 3) { // meet_c: T,F AND; t,f OR
49	        rt = xt&yt; rf = xf&yf; rtt = xtt|ytt; rff = xff|yff;
50	    } else { // op == 4, join_c: T,F OR; t,f AND
51	        rt = xt|yt; rf = xf|yf; rtt = xtt&ytt; rff = xff&yff;
52	    }
53	    out[i] = rt | (rf<<1) | (rtt<<2) | (rff<<3);
54	}
55	
56	extern "C" __global__ void sixteen3_unary(
57	    unsigned char *out, const unsigned char *x, const int op, const unsigned long long n)
58	{
59	    unsigned long long i = (unsigned long long)blockIdx.x * blockDim.x + threadIdx.x;
60	    if (i >= n) return;
61	    unsigned char xv = x[i];
62	    unsigned char xt=(xv>>0)&1, xf=(xv>>1)&1, xtt=(xv>>2)&1, xff=(xv>>3)&1;
63	    unsigned char rt, rf, rtt, rff;
64	    if (op == 0) { rt=xf; rf=xt; rtt=xtt; rff=xff; }       // truth_swap
65	    else if (op == 1) { rt=xt; rf=xf; rtt=xff; rff=xtt; }  // info_swap
66	    else { rt=xf; rf=xt; rtt=xff; rff=xtt; }                // invol
67	    out[i] = rt | (rf<<1) | (rtt<<2) | (rff<<3);
68	}
69	
70	extern "C" __global__ void sixteen3_leq(
71	    unsigned char *out, const unsigned char *x, const unsigned char *y,
72	    const int op, const unsigned long long n)
73	{
74	    unsigned long long i = (unsigned long long)blockIdx.x * blockDim.x + threadIdx.x;
75	    if (i >= n) return;
76	    unsigned char xv = x[i], yv = y[i];
77	    unsigned char xt=(xv>>0)&1, xf=(xv>>1)&1, xtt=(xv>>2)&1, xff=(xv>>3)&1;
78	    unsigned char yt=(yv>>0)&1, yf=(yv>>1)&1, ytt=(yv>>2)&1, yff=(yv>>3)&1;
79	    unsigned char r;
80	    if (op == 0) { // leq_i: subset on all four lanes
81	        r = (!xt||yt) && (!xf||yf) && (!xtt||ytt) && (!xff||yff);
82	    } else if (op == 1) { // leq_t: T,t grow; F,f shrink
83	        unsigned char pos_ok = (!xt||yt) && (!xtt||ytt);
84	        unsigned char neg_ok = (!yf||xf) && (!yff||xff);
85	        r = pos_ok && neg_ok;
86	    } else { // leq_c: T,F grow; t,f shrink
87	        unsigned char con_ok = (!xt||yt) && (!xf||yf);
88	        unsigned char noncon_ok = (!ytt||xtt) && (!yff||xff);
89	        r = con_ok && noncon_ok;
90	    }
91	    out[i] = r;
92	}
93	"#;
94	
95	fn pack(r: Reg16_3) -> u8 {
96	    (r.big_t as u8) | ((r.big_f as u8) << 1) | ((r.small_t as u8) << 2) | ((r.small_f as u8) << 3)
97	}
98	
99	fn unpack(b: u8) -> Reg16_3 {
100	    Reg16_3 {
101	        big_t: b & 1 != 0,
102	        big_f: b & 2 != 0,
103	        small_t: b & 4 != 0,
104	        small_f: b & 8 != 0,
105	    }
106	}
107	
108	/// A tiny xorshift PRNG -- no external `rand` dependency needed for a
109	/// verification sweep whose only requirement is "cover the space", not
