1	//! gpu_dqi_xorsat.rs — GPU brute-force cross-check for the CPU
2	//! Gaussian-elimination XORSAT solver in dqi.rs.
3	//!
4	//! Follows gpu_sixteen3.rs's pattern: one CUDA kernel, JIT-compiled via
5	//! cudarc/NVRTC, launched over the full 2^m assignment space, each thread
6	//! checking one assignment against every clause (packed as a u64
7	//! variable-subset bitmask + rhs bit, m <= 30 here). This pushes
8	//! brute-force verification past what serial CPU brute force in dqi.rs
9	//! can reach (capped at m=24 there, to stay a benchmark rather than a
10	//! multi-hour loop) and cross-checks dqi::xorsat_solve's answer against
11	//! ground truth at that larger scale -- the same "run both, compare, zero
12	//! mismatches" discipline gpu_sixteen3.rs::verify already established for
13	//! the trilattice gates, applied here to the DQI solver.
14	//!
15	//! Hosted only: no CUDA driver in the bare-metal build.
16	
17	use alloc::format;
18	use alloc::string::String;
19	use alloc::vec::Vec;
20	use cudarc::driver::{CudaContext, LaunchConfig, PushKernelArg};
21	use cudarc::nvrtc::compile_ptx;
22	
23	const KERNEL_SRC: &str = r#"
24	extern "C" __global__ void xorsat_brute(
25	    unsigned long long *found_mask, int *found_flag,
26	    const unsigned long long *clause_masks, const unsigned char *clause_rhs,
27	    const int num_clauses, const unsigned long long total)
28	{
29	    unsigned long long i = (unsigned long long)blockIdx.x * blockDim.x + threadIdx.x;
30	    if (i >= total) return;
31	    if (*found_flag) return; // racy early-out is fine: correctness comes from the atomic below
32	    bool ok = true;
33	    for (int c = 0; c < num_clauses; c++) {
34	        unsigned long long parity = __popcll(i & clause_masks[c]) & 1ULL;
35	        bool want = clause_rhs[c] != 0;
36	        if ((parity != 0) != want) { ok = false; break; }
37	    }
38	    if (ok) {
39	        int prev = atomicExch(found_flag, 1);
40	        if (prev == 0) {
41	            *found_mask = i;
42	        }
43	    }
44	}
45	"#;
46	
47	/// Brute-forces every one of the 2^num_vars assignments on GPU for the
48	/// given clause set (same (variable-index-subset, rhs) shape
49	/// `dqi::xorsat_solve` takes), then cross-checks the result directly
50	/// against the CPU elimination solver run on the identical instance.
51	/// Refuses num_vars outside 1..=30: above that a single kernel launch
52	/// stops being the right tool, and 0 has no assignments to brute force.
53	pub fn verify_against_cpu(clauses: &[(Vec<usize>, bool)], num_vars: usize, device: usize) -> String {
54	    if num_vars == 0 || num_vars > 30 {
55	        return format!(
56	            "gpu_dqi_xorsat: refusing num_vars={} (supported: 1..=30 — 2^30 assignments is already the practical ceiling for one launch)",
57	            num_vars
58	        );
