1	#![allow(dead_code)]
2	//! qft.rs — Quantum Fourier Transform Tool
3	//!
4	//! Implements the Quantum Fourier Transform (QFT) and its inverse (IQFT)
5	//! as native kernel commands. The QFT is the core subroutine of Shor's
6	//! period-finding algorithm and many other quantum algorithms.
7	//!
8	//! Circuit structure for n qubits:
9	//!   QFT = H_0 CR_1 H_1 CR_2 CR_1 H_2 ... CR_{n-1} ... CR_1 H_{n-1}
10	//!   IQFT = H_{n-1} CR_1 H_{n-2} CR_2 CR_1 ... H_0 CR_{n-1} ... CR_1
11	//!
12	//! where CR_k = controlled-R_k, R_k = diag(1, e^{2πi/2^k})
13	
14	use alloc::vec::Vec;
15	use alloc::vec;
16	use alloc::string::{String, ToString};
17	use alloc::format;
18	// use libm;
19	
20	/// QFT/IQFT circuit representation
21	#[derive(Clone, Debug)]
22	pub struct QftCircuit {
23	    pub n_qubits: usize,
24	    pub inverse: bool,
25	    pub gates: Vec<QftGate>,
26	}
27	
28	#[derive(Clone, Debug)]
29	pub struct QftGate {
30	    pub kind: QftGateKind,
31	    pub target: usize,
32	    pub control: Option<usize>,
33	    pub k: Option<usize>, // for controlled-R_k: the phase denominator 2^k
34	}
35	
36	#[derive(Clone, Debug, PartialEq, Eq)]
37	pub enum QftGateKind {
38	    H,          // Hadamard
39	    CR,         // Controlled-R_k (phase gate)
40	    SWAP,       // SWAP at the end of QFT (before IQFT)
41	}
