76	            } else if bias == B4::T {
77	                self.qubits[i] = B4::T;
78	                self.coherence_count += 1;
79	                'T'
80	            } else if bias == B4::F {
81	                self.qubits[i] = B4::F;
82	                self.coherence_count += 1;
83	                'F'
84	            } else {
85	                'N'
86	            }
87	        } else {
88	            match q {
89	                B4::T => 'T',
90	                B4::F => 'F',
91	                B4::N => 'N',
92	                B4::B => unreachable!(),
93	            }
94	        }
