102	// ── Modular exponentiation circuit ─────────────────────────────────
103	
104	pub struct BelnapModExp {
105	    pub input_bits: usize,
106	    pub a: u64,
107	    pub n_val: u64,
108	    pub mod_bits: usize,
109	    table: Vec<u64>,
110	}
111	
112	impl BelnapModExp {
113	    pub fn new(input_bits: usize, a: u64, n_val: u64) -> Self {
114	        let mod_bits = if n_val <= 1 { 1 } else {
115	            let mut bits = 0;
116	            let mut v = n_val - 1;
117	            while v > 0 { bits += 1; v >>= 1; }
118	            bits.max(1)
119	        };
120	        let table_size = 1usize << input_bits;
121	        let mut table = Vec::with_capacity(table_size);
122	        for x in 0..table_size {
123	            table.push(mod_pow(a, x as u64, n_val));
124	        }
125	        Self { input_bits, a, n_val, mod_bits, table }
126	    }
127	
128	    /// f(x) = a^x mod N. B-input → B-output (cost 0).
129	    pub fn evaluate(&self, word: &[B4]) -> Vec<B4> {
130	        if word.iter().all(|w| *w == B4::B) {
131	            return vec![B4::B; self.mod_bits];
132	        }
133	        let mut x: u64 = 0;
134	        for (i, w) in word.iter().enumerate() {
135	            if *w == B4::T { x |= 1 << i; }
136	        }
137	        let result = if (x as usize) < self.table.len() {
138	            self.table[x as usize]
139	        } else {
140	            mod_pow(self.a, x, self.n_val)
141	        };
142	        let mut out = Vec::with_capacity(self.mod_bits);
143	        for i in 0..self.mod_bits {
144	            out.push(if (result >> i) & 1 != 0 { B4::T } else { B4::F });
145	        }
146	        out
147	    }
148	
149	    /// Classical period finding.
150	    pub fn find_period(&self) -> u64 {
151	        let mut val: u64 = 1;
152	        for r in 1..=self.n_val {
153	            val = (val * self.a) % self.n_val;
154	            if val == 1 { return r; }
155	        }
156	        0
157	    }
158	}
159	
160	fn mod_pow(mut base: u64, mut exp: u64, modulus: u64) -> u64 {
161	    if modulus == 0 { return 0; }
162	    if modulus == 1 { return 0; }
163	    let mut result: u64 = 1;
164	    base %= modulus;
165	    while exp > 0 {
166	        if exp & 1 != 0 { result = (result * base) % modulus; }
167	        exp >>= 1;
168	        base = (base * base) % modulus;
169	    }
170	    result
171	}
