348	mod tests {
349	    use super::*;
350	
351	    #[test]
352	    fn test_hadamard() {
353	        assert_eq!(b4_hadamard(B4::T), B4::B);
354	        assert_eq!(b4_hadamard(B4::F), B4::B);
355	        assert_eq!(b4_hadamard(B4::B), B4::T);
356	        assert_eq!(b4_hadamard(B4::N), B4::N);
357	    }
358	
359	    #[test]
360	    fn test_hadamard_layer() {
361	        let mut reg = BelnapRegister::classical(4);
362	        reg.apply_hadamard_layer();
363	        assert!(reg.qubits.iter().all(|&q| q == B4::B));
364	        assert_eq!(reg.coherence_count, 4);
365	    }
366	
367	    #[test]
368	    fn test_xor() {
369	        assert_eq!(b4_xor(B4::T, B4::F), B4::T);
370	        assert_eq!(b4_xor(B4::T, B4::T), B4::F);
371	        assert_eq!(b4_xor(B4::B, B4::T), B4::B);
372	    }
373	
374	    #[test]
375	    fn test_mod_exp_b_propagation() {
376	        let me = BelnapModExp::new(4, 7, 15);
377	        let input = vec![B4::B; 4];
378	        let out = me.evaluate(&input);
379	        assert!(out.iter().all(|&q| q == B4::B));
380	    }
381	
382	    #[test]
383	    fn test_shor_n15_a7() {
384	        let r = run_belnap_shor(4, 7, 15);
385	        assert_eq!(r.period_cl, 4);
386	        assert_eq!(r.hadamard_coherence, 4);
387	        assert_eq!(r.mod_exp_coherence, 0);
388	        assert_eq!(r.b_bias_coherence, 8);  // 2n
389	        assert_eq!(r.t_bias_coherence, 4);  // n
390	        assert_eq!(r.ratio, 2.0);
391	        assert!(r.mod_exp_all_b);
392	        assert!(r.b_bias_preserves);
393	        assert!(r.t_bias_collapses);
394	    }
395	
396	    #[test]
397	    fn test_shor_n21_a5() {
398	        let r = run_belnap_shor(5, 5, 21);
399	        assert_eq!(r.period_cl, 6);
400	        assert_eq!(r.b_bias_coherence, 10);
401	        assert_eq!(r.t_bias_coherence, 5);
402	    }
403	
404	    #[test]
405	    fn test_sic_povm() {
406	        assert!(verify_sic_povm());
407	    }
408	}
