            basis = next;
            degree += 1;
            denom = mul_mod(denom, sub_mod(xi, xj, p), p);
        }
        let scale = mul_mod(yi, mod_inv(denom, p), p);
        for d in 0..k {
            coeffs[d] = add_mod(coeffs[d], mul_mod(basis[d], scale, p), p);
